        throw new IllegalArgumentException("Invalid input values");
    }

    int count = 0;
    for (int year = Y; year <= Y + N * 4; year++) {
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            if (++count == N) {
                return year;
            }
