import java.util.ArrayList;
import java.util.List;

public class PermutationGenerator {

    public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        if (nums == null || nums.length == 0) {
            return result;
        }
        permuteHelper(nums, 0, result);
        return result;
    }

    private void permuteHelper(int[] nums, int start, List<List<Integer>> result) {
        if (start == nums.length - 1) {
            List<Integer> list = new ArrayList<>();
            for (int num : nums) {
                list.add(num);
            }
            result.add(list);
            return;
        }
        for (int i = start; i < nums.length; i++) {
            swap(nums, start, i);
            permuteHelper(nums, start + 1, result);
            swap(nums, start, i);
        }
    }

    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }

    // Test cases
    public static void main(String[] args) {
        PermutationGenerator generator = new PermutationGenerator();

        // Test case 1
        int[] nums1 = {1, 2, 3};
        System.out.println("Test case 1: " + generator.permute(nums1));

        // Test case 2
        int[] nums2 = {0, 1};
        System.out.println("Test case 2: " + generator.permute(nums2));

        // Test case 3
        int[] nums3 = {1};
        System.out.println("Test case 3: " + generator.permute(nums3));
    }
}
```

