public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    for (String str : strings) {
        for (int i = 0; i < str.length(); i++) {
            for (int j = i + 1; j <= str.length(); j++) {
                String sub = str.substring(i, j);
                String reversedSub = new StringBuilder(sub).reverse().toString();
                boolean isFound = false;

                for (String s : strings) {
                    if (s.contains(sub) || s.contains(reversedSub)) {
                        isFound = true;
                        break;
                    }
                }

                if (isFound && sub.length() > maxLength) {
                    maxLength = sub.length();
                }
            }
        }
    }

    return maxLength;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Track the maximum length of the substring
    int maxLength = 0;

    // Iterate through each pair of strings to find the largest valid substring
    for (String str1 : strings) {
        for (String str2 : strings) {
            if (!str1.equals(str2)) {
                // Check if str1 or its reverse is a substring of str2
                if (str2.contains(str1) || str2.contains(new StringBuilder(str1).reverse().toString())) {
                    // Update the maximum length if the current substring is larger
                    maxLength = Math.max(maxLength, str1.length());
                }
            }
        }
    }

    return maxLength;
}

