    markDeposit(grid, i - 1, j, rows, cols);
    markDeposit(grid, i + 1, j, rows, cols);
    markDeposit(grid, i, j - 1, rows, cols);
    markDeposit(grid, i, j + 1, rows, cols);
    markDeposit(grid, i - 1, j - 1, rows, cols);
    markDeposit(grid, i - 1, j + 1, rows, cols);
    markDeposit(grid, i + 1, j - 1, rows, cols);
    markDeposit(grid, i + 1, j + 1, rows, cols);
