public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles must be non-negative.");
    }
    // Base case: 1 triangle divides the plane into 2 regions
    if (N == 0) {
        return 2;
    }
    // Each new triangle intersects all previous triangles, creating 2 new regions per intersection
    return 2 + N * 2;
}
```

