/**
 * Calculates the maximum number of regions a plane can be divided into given N triangles.
 * <p>
 * The formula to calculate the maximum number of regions R given N triangles is:
 * R = 2 + 3 * N
 * where N is the number of triangles.
 *
 * @param N the number of triangles
 * @return the maximum number of regions
 */
public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("The number of triangles must be non-negative.");
    }
    return 2 + 3 * N;
}
