public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start.length != 2 || end.length != 2) {
        throw new IllegalArgumentException("Invalid start or end coordinates");
    }

    List<Integer>[] graph = new List[n*n];
    for (int i = 0; i < graph.length; i++) {
        graph[i] = new ArrayList<>();
    }

    for (int[] path : paths) {
        if (path.length != 2) {
            throw new IllegalArgumentException("Invalid path");
        }
        int u = path[0], v = path[1];
        graph[u].add(v);
        graph[v].add(u);
    }

    boolean[] visited = new boolean[n*n];
    boolean[] onStack = new boolean[n*n];

    if (hasCycle(graph, visited, onStack, start[0], end[0])) {
        return "cannot be travelled";
    }

    return "can be travelled";
}

private static boolean hasCycle(List<Integer>[] graph, boolean[] visited, boolean[] onStack, int u, int target) {
    if (u == target) {
        return true;
    }
    visited[u] = true;
    onStack[u] = true;

    for (int v : graph[u]) {
        if (!visited[v] && hasCycle(graph, visited, onStack, v, target)) {
            return true;
        } else if (onStack[v]) {
            return true;
        }
    }

    onStack[u] = false;
    return false;
}
