public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create an adjacency list to represent the maze
    List<Integer>[] maze = new List[n * n];
    for (int i = 0; i < maze.length; i++) {
        maze[i] = new ArrayList<>();
    }

    // Populate the adjacency list with the given paths
    for (int[] path : paths) {
        int from = path[0] * n + path[1];
        int to = path[2] * n + path[3];
        maze[from].add(to);
        maze[to].add(from);
    }

    // Check if the starting and ending coordinates are valid
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n ||
        end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Use BFS to determine if there is a path from start to end
    boolean[] visited = new boolean[n * n];
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(start[0] * n + start[1]);
    visited[start[0] * n + start[1]] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        int x = current / n;
        int y = current % n;

        if (x == end[0] && y == end[1]) {
            return "can be travelled";
        }

        for (int neighbor : maze[current]) {
            int nx = neighbor / n;
            int ny = neighbor % n;
            if (!visited[neighbor] && Math.abs(x - nx) + Math.abs(y - ny) == 1) {
                visited[neighbor] = true;
                queue.offer(neighbor);
            }
        }
    }

    // If no path is found, return "cannot be travelled"
    return "cannot be travelled";
}
