public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    return dfs(paths, start[0], end[0], visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int[][] paths, int current, int end, boolean[] visited) {
    if (current == end) {
        return true;
    }
    visited[current] = true;
    for (int[] path : paths) {
        if (path[0] == current && !visited[path[1]]) {
            if (dfs(paths, path[1], end, visited)) {
                return true;
            }
        }
        if (path[1] == current && !visited[path[0]]) {
            if (dfs(paths, path[0], end, visited)) {
                return true;
            }
        }
    }
    visited[current] = false;
    return false;
}

