private static boolean dfs(int x, int y, int endX, int endY, boolean[][] visited, int[][] paths) {
    if (x == endX && y == endY) {
        return true;
    }
    visited[x][y] = true;
    for (int i = 0; i < paths.length; i++) {
        int[] path = paths[i];
        if ((path[0] == x && path[1] == y && path[2] == 1) || (path[0] == y && path[1] == x && path[2] == 1)) {
            int nextX = path[0] == x ? path[1] : path[0];
            int nextY = path[0] == x ? path[2] : path[1];
            if (nextX >= 0 && nextX < visited.length && nextY >= 0 && nextY < visited[nextX].length && !visited[nextX][nextY]) {
                if (dfs(nextX, nextY, endX, endY, visited, paths)) {
                    return true;
                }
            }
        }
    }
    return false;
}
