public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    Set<String> visited = new HashSet<>();
    Map<String, List<String>> graph = new HashMap<>();

    // Build the graph
    for (int[] path : paths) {
        String from = path[0] + "," + path[1];
        String to = path[2] + "," + path[3];
        graph.putIfAbsent(from, new ArrayList<>());
        graph.putIfAbsent(to, new ArrayList<>());
        graph.get(from).add(to);
        graph.get(to).add(from);
    }

    // Depth-First Search to find a path from start to end
    String startStr = start[0] + "," + start[1];
    String endStr = end[0] + "," + end[1];
    if (dfs(graph, startStr, endStr, visited)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static boolean dfs(Map<String, List<String>> graph, String current, String end, Set<String> visited) {
    if (current.equals(end)) {
        return true;
    }
    visited.add(current);
    for (String neighbor : graph.get(current)) {
        if (!visited.contains(neighbor)) {
            if (dfs(graph, neighbor, end, visited)) {
                return true;
            }
        }
    }
    visited.remove(current);
    return false;
}
