public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        graph.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
    }

    return dfs(0, -1, graph, hasApple) * 2;
}

private int dfs(int node, int parent, Map<Integer, List<Integer>> graph, boolean[] hasApple) {
    int time = 0;
    for (int neighbor : graph.getOrDefault(node, new ArrayList<>())) {
        if (neighbor == parent) continue;
        int neighborTime = dfs(neighbor, node, graph, hasApple);
        if (neighborTime > 0 || hasApple[neighbor]) {
            time += neighborTime + 2;
        }
    }
    return time;
}
