public class Solution {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        ArrayList<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int[] edge : edges) {
            adj[edge[0]].add(edge[1]);
            adj[edge[1]].add(edge[0]);
        }

        return helper(0, adj, hasApple, new boolean[n])[0];
    }

    private int[] helper(int node, ArrayList<Integer>[] adj, boolean[] hasApple, boolean[] visited) {
        visited[node] = true;
        boolean hasAppleHereOrDescendant = hasApple[node];
        int time = 0;

        for (int child : adj[node]) {
            if (!visited[child]) {
                int[] childResult = helper(child, adj, hasApple, visited);
                if (childResult[0] > 0 || hasAppleHereOrDescendant) {
                    time += childResult[0] + 2;
                    hasAppleHereOrDescendant = true;
                }
            }
        }

        return new int[]{time, hasAppleHereOrDescendant ? 1 : 0};
    }
}
