    dp[0] = true;

    for (int num : nums) {
        for (int i = sum * n; i >= num; i--) {
            dp[i] = dp[i] || dp[i - num];
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[sum * i]) {
            return true;
