public boolean splitArraySameAverage(int[] nums) {
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int n = nums.length;
    boolean[][] dp = new boolean[n + 1][totalSum + 1];
    dp[0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = totalSum; j >= num; j--) {
            dp[i][j] = dp[i - 1][j] || dp[i - 1][j - num];
        }
    }

    for (int i = 1; i < n; i++) {
        int sum1 = 0;
        for (int j = 0; j < i; j++) {
            sum1 += nums[j];
        }
        int sum2 = totalSum - sum1;
        if (sum1 * n == sum2 * i && dp[i][sum1] && dp[n - i][sum2]) {
            return true;
        }
    }

    return false;
