public class Solution {
    public boolean splitArraySameAverage(int[] A) {
        int sum = 0;
        for (int a : A) {
            sum += a;
        }
        int n = A.length;

        // If the total sum is 0, we cannot split it into two non-empty subsets with the same average
        if (sum == 0) {
            return false;
        }

        // Check if there is any subset with the required average
        for (int i = 1; i <= n / 2; i++) {
            if (sum * i % n == 0 && hasSum(A, i, sum * i / n)) {
                return true;
            }
        }
        return false;
    }

    private boolean hasSum(int[] A, int k, int target) {
        Boolean[][] dp = new Boolean[A.length + 1][target + 1];
        return helper(A, k, target, 0, dp);
    }

    private boolean helper(int[] A, int k, int target, int start, Boolean[][] dp) {
        if (k == 0 && target == 0) {
            return true;
        }
        if (k == 0 || target == 0 || start >= A.length) {
            return false;
        }

        if (dp[start][target] != null) {
            return dp[start][target];
        }

        boolean include = false;
        if (A[start] <= target) {
            include = helper(A, k - 1, target - A[start], start + 1, dp);
        }

        boolean exclude = helper(A, k, target, start + 1, dp);

        dp[start][target] = include || exclude;
        return dp[start][target];
    }
}
