        HashSet<Integer> s = new HashSet<>();
        for (int j = 0; j < 1 << i; j++) {
            int sumJ = 0;
            for (int k = 0; k < i; k++) {
                if (((j >> k) & 1) == 1) {
                    sumJ += nums[k];
                }
            }
            s.add(sumJ);
        }
        for (int j = 0; j < 1 << (n - i); j++) {
            int sumJ = 0;
            for (int k = 0; k < n - i; k++) {
                if (((j >> k) & 1) == 1) {
                    sumJ += nums[i + k];
                }
            }
            if (sumJ == (sum - sumJ) && s.contains(sum - sumJ)) {
                return true;
            }
        }
    }
    return false;
}
