public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("Input array cannot be null or empty");
    }

    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    if (n == 2) {
        return Math.min(cost[0], cost[1]);
    }

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
