    int uniqueCount = 0;
    int mask = (1 << k) - 1;
    int currentHash = 0;

    for (int i = 0; i < s.length(); i++) {
        currentHash = ((currentHash << 1) | (s.charAt(i) - '0')) & mask;
        if (i >= k - 1) {
            if (!seen[currentHash]) {
                seen[currentHash] = true;
                uniqueCount++;
            }
        }
    }

    return uniqueCount == (1 << k);
}
