public int minInsertions(String s) {
    int open = 0;
    int close = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            if (close % 2 == 1) {
                insertions++;
                close--;
            }
            open++;
        } else {
            close++;
        }

        if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
            if (close > 1) {
                insertions++;
            }
            i++;
        } else {
            insertions++;
        }
    }

    insertions += open * 2;
    insertions += close * 2;

    return insertions;
}
