public class MinInsertions {
    /**
     * Calculates the minimum number of insertions required to make the given string of parentheses balanced.
     *
     * @param s The input string consisting of '(' and ')'.
     * @return The minimum number of insertions required.
     */
    public int minInsertions(String s) {
        int open = 0; // To keep track of the number of unmatched '('
        int result = 0; // To count the number of insertions
        int i = 0; // Index to iterate through the string

        while (i < s.length()) {
            char c = s.charAt(i);

            if (c == '(') {
                open++;
                i++;
            } else {
                // Check if there is an unmatched '(' to pair with this ')'
                if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                    i += 2;
                } else {
                    result++;
                    i++;
                }

                // If we have an unmatched '(', append ')' to balance it
                if (open > 0) {
                    open--;
                    result++;
                }
            }
        }

        // Add the remaining unmatched '(' with a corresponding ')'
        result += open * 2;

        return result;
    }
}
