public int maxAbsoluteSum(int[] nums) {
    int maxSum = 0;
    int minSum = 0;
    int currentMaxSum = 0;
    int currentMinSum = 0;

    for (int num : nums) {
        currentMaxSum = Math.max(currentMaxSum + num, 0);
        maxSum = Math.max(maxSum, currentMaxSum);

        currentMinSum = Math.min(currentMinSum + num, 0);
        minSum = Math.min(minSum, currentMinSum);
    }

    return Math.max(maxSum, Math.abs(minSum));
