public class MinFibonacciNumbers {

    /**
     * Finds the minimum number of Fibonacci numbers whose sum is equal to k.
     *
     * @param k The target sum.
     * @return The minimum number of Fibonacci numbers required.
     */
    public int findMinFibonacciNumbers(int k) {
        List<Integer> fibNumbers = new ArrayList<>();
        fibNumbers.add(1);
        fibNumbers.add(1);

        // Generate Fibonacci numbers up to k
        while (true) {
            int nextNumber = fibNumbers.get(fibNumbers.size() - 1) + fibNumbers.get(fibNumbers.size() - 2);
            if (nextNumber > k) {
                break;
            }
            fibNumbers.add(nextNumber);
        }

        int count = 0;
        int index = fibNumbers.size() - 1;

        while (k > 0 && index >= 0) {
            if (fibNumbers.get(index) <= k) {
                k -= fibNumbers.get(index);
                count++;
            }
            index--;
        }

        return count;
    }

    public static void main(String[] args) {
        MinFibonacciNumbers solution = new MinFibonacciNumbers();
        System.out.println(solution.findMinFibonacciNumbers(7));  // Output: 2
        System.out.println(solution.findMinFibonacciNumbers(10)); // Output: 2
        System.out.println(solution.findMinFibonacciNumbers(19)); // Output: 3
    }
}
