public class MinFibonacciNumbers {

    /**
     * Finds the minimum number of Fibonacci numbers whose sum is equal to k.
     *
     * @param k the integer k
     * @return the minimum number of Fibonacci numbers whose sum is equal to k
     */
    public static int findMinFibonacciNumbers(int k) {
        if (k <= 0) {
            throw new IllegalArgumentException("k must be a positive integer.");
        }

        int result = 0;
        List<Integer> Fibonacci = generateFibonacci(k);

        int index = Fibonacci.size() - 1;
        while (k > 0) {
            if (Fibonacci.get(index) <= k) {
                k -= Fibonacci.get(index);
                result++;
            }
            index--;
        }

        return result;
    }

    private static List<Integer> generateFibonacci(int k) {
        List<Integer> list = new ArrayList<>();
        int a = 1, b = 1;
        list.add(a);
        list.add(b);

        while (true) {
            int next = a + b;
            if (next > k) {
                break;
            }
            list.add(next);
            a = b;
            b = next;
        }

        return list;
    }

    public static void main(String[] args) {
        // Test cases to verify the solution
        System.out.println(findMinFibonacciNumbers(7));  // Output: 2
        System.out.println(findMinFibonacciNumbers(10)); // Output: 2
        System.out.println(findMinFibonacciNumbers(19)); // Output: 3
    }
}
