    // Generate Fibonacci numbers up to k
    List<Integer> fibNumbers = new ArrayList<>();
    int a = 1, b = 1;
    while (a <= k) {
        fibNumbers.add(a);
        int temp = a + b;
        a = b;
        b = temp;
    }

    // Use the largest Fibonacci number less than or equal to k
    int count = 0;
    while (k > 0) {
        int maxFib = fibNumbers.get(fibNumbers.size() - 1);
        if (maxFib <= k) {
            k -= maxFib;
            count++;
        } else {
            fibNumbers.remove(fibNumbers.size() - 1);
        }
    }

    return count;
}
