    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
        }
    }

    // Check if kth factor exists
    if (k > factors.size()) {
        return -1;
    }

    // Return the kth factor
    return factors.get(k - 1);
}
