private int backtrack(String s, HashSet<String> seen) {
    if (s.isEmpty()) {
        return 0;
    }

    int maxSplit = 0;
    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        if (!seen.contains(prefix)) {
            seen.add(prefix);
            maxSplit = Math.max(maxSplit, 1 + backtrack(s.substring(i), seen));
            seen.remove(prefix);
        }
    }
    return maxSplit;
}
