public class MaxUniqueSplit {
    public int maxUniqueSplit(String s) {
        return splitHelper(s, 0, new HashSet<>());
    }

    private int splitHelper(String s, int index, Set<String> uniqueSubstrings) {
        if (index == s.length()) {
            return uniqueSubstrings.size();
        }

        int maxUnique = 0;
        for (int i = index + 1; i <= s.length(); i++) {
            String substring = s.substring(index, i);
            if (!uniqueSubstrings.contains(substring)) {
                uniqueSubstrings.add(substring);
                maxUnique = Math.max(maxUnique, splitHelper(s, i, uniqueSubstrings));
                uniqueSubstrings.remove(substring);
            }
        }

        return maxUnique;
    }

    public static void main(String[] args) {
        MaxUniqueSplit solution = new MaxUniqueSplit();
        System.out.println(solution.maxUniqueSplit("ababccc")); // Output: 5
    }
}
