public class SmallestStringGenerator {
    /**
     * Returns the lexicographically smallest string of length n and value k.
     *
     * @param n The length of the string.
     * @param k The value of the string.
     * @return The lexicographically smallest string.
     */
    public String getSmallestString(int n, int k) {
        char[] result = new char[n];
        Arrays.fill(result, 'a'); // Initialize with 'a' to minimize the string value
        k -= n; // Subtract the value of 'n' a's to find the remaining value needed

        int index = n - 1;
        while (k > 0) {
            int add = Math.min(25, k); // Add the maximum possible value that keeps the string lexicographically smallest
            result[index] += add;
            k -= add;
            index--;
        }

        return new String(result);
    }

    public static void main(String[] args) {
        SmallestStringGenerator generator = new SmallestStringGenerator();
        System.out.println(generator.getSmallestString(3, 27)); // Output: "aay"
        System.out.println(generator.getSmallestString(5, 73)); // Output: "aaszz"
    }
}
