        List<Integer> steppingNumbers = new ArrayList<>();
        Queue<Integer> queue = new LinkedList<>();

        // Initialize the queue with numbers from 0 to 9
        for (int i = 0; i < 10; i++) {
            if (i >= low) {
                steppingNumbers.add(i);
            }
            if (i > 0) {
                queue.offer(i);
            }
        }

        while (!queue.isEmpty()) {
            int current = queue.poll();

            // Find the last digit of the current number
            int lastDigit = current % 10;

            // Generate the next stepping number by adding 1 to the last digit
            if (lastDigit < 9 && current * 10 + (lastDigit + 1) >= low && current * 10 + (lastDigit + 1) <= high) {
                steppingNumbers.add(current * 10 + (lastDigit + 1));
                queue.offer(current * 10 + (lastDigit + 1));
            }

            // Generate the next stepping number by subtracting 1 from the last digit
            if (lastDigit > 0 && current * 10 + (lastDigit - 1) >= low && current * 10 + (lastDigit - 1) <= high) {
                steppingNumbers.add(current * 10 + (lastDigit - 1));
                queue.offer(current * 10 + (lastDigit - 1));
            }
        }

        Collections.sort(steppingNumbers);
        return steppingNumbers;
    }
