public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }

    int count = 0;
    for (long i = 1; i <= n; i++) {
        count += (i / 10) * 10 + Math.min(Math.max(i % 10 - 1, 0), 1) + ((i / 10) % 10 >= 1 ? 1 : 0);
    }
    return count;
}
