public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;

    int count = 0;

    // Helper function to check if a number is a perfect square
    boolean isPerfectSquare(int num) {
        int sqrt = (int) Math.sqrt(num);
        return sqrt * sqrt == num;
    }

    // Helper function to perform DFS and count permutations
    void dfs(int[] visited, int index, int num) {
        if (index == n) {
            count++;
            return;
        }

        for (int i = 0; i < n; i++) {
            if (visited[i] == 0 && isPerfectSquare(A[index] + A[i])) {
                visited[i] = 1;
                dfs(visited, index + 1, A[i]);
                visited[i] = 0;
            }
        }
    }

    // Array to track visited elements
    int[] visited = new int[n];

    // Start DFS from each element
    for (int i = 0; i < n; i++) {
        visited[i] = 1;
        dfs(visited, 1, A[i]);
        visited[i] = 0;
    }

    return count;
}
