public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int N = A.length;
    boolean[] used = new boolean[N];
    int count = 0;

    backtrack(A, used, 0, count);
    return count;
}

private static void backtrack(int[] A, boolean[] used, int index, int count) {
    if (index == A.length - 1) {
        count++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (used[i]) {
            continue;
        }

        if (index == 0) {
            used[i] = true;
            backtrack(A, used, index + 1, count);
            used[i] = false;
        } else {
            if (isPerfectSquare(A[index - 1] + A[i])) {
                used[i] = true;
                backtrack(A, used, index + 1, count);
                used[i] = false;
            }
        }
    }
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}
