import java.util.Arrays;

public class SquarePermutations {

    public static int squarePermutations(int[] A) {
        int N = A.length;
        boolean[] used = new boolean[N];
        int count = 0;

        permute(A, used, new int[N], 0, count);
        return count;

    }

    private static void permute(int[] A, boolean[] used, int[] temp, int index, int count) {
        if (index == A.length) {
            count = isValidPermutation(A, temp) ? count + 1 : count;
            return;
        }

        for (int i = 0; i < A.length; i++) {
            if (!used[i]) {
                used[i] = true;
                temp[index] = A[i];
                permute(A, used, temp, index + 1, count);
                used[i] = false; // backtrack
            }
        }
    }

    private static boolean isValidPermutation(int[] A, int[] temp) {
        for (int i = 0; i < temp.length - 1; i++) {
            int sum = temp[i] + temp[i + 1];
            if (!isPerfectSquare(sum)) {
                return false;
            }
        }
        return true;
    }

    private static boolean isPerfectSquare(int sum) {
        int root = (int) Math.sqrt(sum);
        return sum == root * root;
    }

    public static void main(String[] args) {
        System.out.println(squarePermutations(new int[]{1, 17, 8})); // Output: 2
        System.out.println(squarePermutations(new int[]{2, 2, 2})); // Output: 1
    }
}
