public static int squarePermutations(int[] A) {
    int result = 0;
    int n = A.length;

    boolean[] used = new boolean[n];

    for (int i = 0; i < n; i++) {
        used[i] = true;
        backtrack(A, result, 1, used, i);
        used[i] = false;
    }

    return result;
}

private static void backtrack(int[] A, int result, int pos, boolean[] used, int prev) {
    if (pos == A.length) {
        result++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (used[i] || !isPerfectSquare(A[i], prev)) continue;

        used[i] = true;
        backtrack(A, result, pos + 1, used, A[i]);
        used[i] = false;
    }
}

private static boolean isPerfectSquare(int num, int prev) {
    int sum = num + prev;
    int root = (int) Math.sqrt(sum);
    return root * root == sum;
}
