        if (stack.isEmpty() || heights[index] >= heights[stack.peek()]) {
            stack.push(index);
            index++;
        } else {
            int topOfStack = stack.pop();
            int area = heights[topOfStack] * 
                       (stack.isEmpty() ? index : index - stack.peek() - 1);
            maxArea = Math.max(maxArea, area);
        }
    }

    while (!stack.isEmpty()) {
        int topOfStack = stack.pop();
        int area = heights[topOfStack] * 
                   (stack.isEmpty() ? index : index - stack.peek() - 1);
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
