public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];

    // Initialize left and right arrays
    for (int i = 0; i < n; i++) {
        left[i] = i;
        right[i] = i;
    }

    // Fill left array with the nearest smaller element on the left
    for (int i = 1; i < n; i++) {
        int p = i - 1;
        while (p >= 0 && heights[i] <= heights[p]) {
            p = left[p];
        }
        left[i] = p;
    }

    // Fill right array with the nearest smaller element on the right
    for (int i = n - 2; i >= 0; i--) {
        int p = i + 1;
        while (p < n && heights[i] <= heights[p]) {
            p = right[p];
        }
        right[i] = p;
    }

    // Calculate the maximum rectangle area
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int h = heights[i];
        int w = right[i] - left[i] - 1;
        maxArea = Math.max(maxArea, h * w);
    }

    return maxArea;
