import java.util.Arrays;

public class SmallestIntegerFinder {

    /**
     * Finds the smallest integer that can be formed by rearranging the digits of the given positive integer n,
     * which is greater than n. Returns -1 if not possible.
     *
     * @param n The input positive integer.
     * @return The smallest rearranged integer greater than n, or -1 if not possible.
     */
    public static int findSmallestInteger(int n) {
        char[] digits = Integer.toString(n).toCharArray();
        int length = digits.length;

        // Start from the right, find the first digit that is smaller than the digit to its right
        int i;
        for (i = length - 2; i >= 0; i--) {
            if (digits[i] < digits[i + 1]) {
                break;
            }
        }

        // If no such digit is found, return -1 (no greater arrangement possible)
        if (i == -1) {
            return -1;
        }

        // Find the smallest digit on the right side of (i-th digit) that is greater than digits[i]
        int j;
        for (j = length - 1; j > i; j--) {
            if (digits[j] > digits[i]) {
                break;
            }
        }

        // Swap the found digits
        char temp = digits[i];
        digits[i] = digits[j];
        digits[j] = temp;

        // Sort the digits after the (i + 1)-th digit
        Arrays.sort(digits, i + 1, length);

        // Convert the digits back to an integer
        long result = Long.parseLong(String.valueOf(digits));

        // Check if the result is within the int range
        if (result <= Integer.MAX_VALUE) {
            return (int) result;
        } else {
            return -1;
        }
    }

    public static void main(String[] args) {
        System.out.println(findSmallestInteger(12)); // Output: 21
        System.out.println(findSmallestInteger(21)); // Output: -1
        System.out.println(findSmallestInteger(536)); // Output: 563
        System.out.println(findSmallestInteger(9836)); // Output: 9863
        System.out.println(findSmallestInteger(123456789)); // Output: 123456798
        System.out.println(findSmallestInteger(987654321)); // Output: -1
    }
}
