            result.add("9" + symmetry + "6");
            result.add("8" + symmetry + "8");
            return;
        }
        helper(n, result, "0" + symmetry + "0");
        helper(n, result, "1" + symmetry + "1");
        helper(n, result, "8" + symmetry + "8");
    }

    public static void main(String[] args) {
