            return new ArrayList<>();
        }

        List<String> res = new ArrayList<>();
        if (n == 1) {
            res.add("0");
            res.add("1");
            res.add("8");
        } else if (n == 2) {
            res.add("11");
            res.add("69");
            res.add("88");
            res.add("96");
        } else {
            List<String> prev = centerSymmetricNumbers(n - 2);
            for (String s : prev) {
                res.add("1" + s + "1");
                res.add("6" + s + "9");
                res.add("8" + s + "8");
                res.add("9" + s + "6");
            }
            if (n % 2 != 0) {
                List<String> singleDigit = List.of("0", "1", "8");
                for (String s : singleDigit) {
                    res.add(s);
                }
            }
        }

        return res;
    }

    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // Output: [11, 69, 88, 96]
