public class WordReverser {

    /**
     * Reverses the characters of each word in the given string while maintaining the original word order.
     *
     * @param s The input string containing words separated by spaces.
     * @return The string with characters of each word reversed.
     */
    public static String reverseWords(String s) {
        if (s == null || s.isEmpty()) {
            return s;
        }

        String[] words = s.split(" ");
        StringBuilder result = new StringBuilder();

        for (String word : words) {
            StringBuilder reversedWord = new StringBuilder(word).reverse();
            result.append(reversedWord).append(" ");
        }

        return result.trim();
    }

    public static void main(String[] args) {
        String input = "Mr Ding";
        String output = reverseWords(input);
        System.out.println(output); // Output: rM gniD
    }
}
